#!/usr/bin/env python3
"""Turn 35 Wave 88: THE 50% RESALE RULE, THE CAPTAIN CRITERIA, AND A FOURTH CONTAMINATION.

Wave 88's centrepieces:

1. THE 50% RESALE RULE, which the corpus did not carry and which prices every transfer
   decision: **a player sells for about half of what you paid for him.** Two independent
   sources, one from DLS Classic's own wiki and one from a DLS2018 guide, give the same figure
   and the same worked example. That single number reframes the corpus's transfer advice -
   buying is a sunk cost, and the only way to recover value is to keep and coach.

2. THE CAPTAIN CRITERIA, REFINED. The corpus says "pick the best attacker". The sources add
   the detail that makes it actionable: a fast forward with *minimum* shooting who can at
   least shoot, **never a goalkeeper or a defender**, an **80-stamina floor** rather than pace
   alone, and two named long-term picks (Foden and Nunez) because they will still fit a gold
   team later.

3. A FOURTH CONTAMINATION, and the general rule that falls out of it. Searches on the transfer
   market and on Dream Draft returned FIFA Ultimate Team trading methods, FPL draft strategy
   and Mobile Legends drafting. **Any DLS topic with a famous analogue in another game gets
   contaminated** - so the standing rule is to include "Dream League Soccer" in the query and
   to discard on sight any source mentioning SBCs, Weekend League, FUT, chemistry styles,
   waivers or bans.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w88')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_tm=new_ev("Two searches on DLS transfer-market strategy and on Dream Draft strategy, both heavily contaminated by FIFA/EA FC Ultimate Team trading methods (sniping filters, SBC demand cycles, Weekend League timing, the 5% EA tax, FUTBIN), Fantasy Premier League draft strategy (positional scarcity, waivers) and Mobile Legends drafting (bans, counter-picks, win conditions). The DLS-specific material recovered: dream-league-soccer.fandom.com/wiki/Free_Transfers_(DLS_Classic) (since DLS 2016h free transfers do not exist and a released player sells for half its purchase value), LevelWinner DLS2018 guide (8 Apr 2018 - the same 50% rule with a worked 1,400-to-700 example), r/DreamLeagueSoccer 1awg1h6 'Best Starting Captain You Can Pick Out' (21 Feb 2024 - never a GK or a defender; a fast forward with minimum shooting), r/DreamLeagueSoccer zwih6d (27 Dec 2022 - the 200-300 coin coach-farming band and playing Career mode), gamingonphone DLS26 beginners guide (21 Jan 2026 - buying and selling refreshes the market), r/DreamLeagueSoccer ktwxpz 'A Beginner's Guide to DLS' (9 Jan 2021 - the first purchase should be an RM, an LM and a CM for no more than 500 coins total; the captain should be a tall CF or WF above 180cm with shooting and speed above 80), r/DreamLeagueSoccer 18dqq9e 'Beginners guide to DLS(24)' (30 Jan 2024 - fitness coaches first, 2 common techs per 8 rare fitness coaches, 1 rare plus 4 commons for GKs, and the preferred per-position stat targets including 90+ GKR with a 0-10 difference to GKH), r/DreamLeagueSoccer 15bpnih (28 Jul 2023 - never use the best XI button, and the per-position attribute checklist), r/DreamLeagueSoccer 1rx01zi (18 Mar 2026 - the footedness placement and the two-striker inversion)",
    "THE 50% RESALE RULE, THE CAPTAIN CRITERIA, AND A FOURTH CONTAMINATION. (1) THE 50% RESALE RULE, which the corpus did not carry and which prices every transfer decision: 'Since Dream League Soccer 2016h, **free transfers do not exist. Instead of releasing players, one must sell the player for half its purchase value.** They will go on to the market, priced at their value.' A second, independent source gives the same figure with a worked example: 'players who are sold on the transfer market will fetch a value of about **50 percent of the purchase price** - for example, a player you may have bought for 1,400 gold will only sell for about 700 gold.' So **buying a player is a sunk cost of half his price**, which reframes the corpus's transfer advice: the only way to recover value is to keep and coach, and the coach-farming loop (buy at 200-300, release for Common coaches) is therefore a deliberate loss-maker you run for coaches, not coins. (2) THE CAPTAIN CRITERIA, REFINED: '**You always want to get a fast forward with minimum shooting that can at least shoot.** These captains should help you get your first event win and your potential second legendary. **YOU SHOULD NEVER PICK OUT A GOALKEEPER OR A DEFENDER!**' A commenter adds the floor that matters more than pace: '**Get a player with high stamina as well, not just pace. I set a benchmark of min 80 stamina**, so in my book, many players on this list should be dropped. **Foden and Nunez are the best in this list for long term**, they (especially Foden) could still fit in your team when you get a full gold team.' And the original guide's fuller version: a CF or WF who is 'reasonably tall (above 180cm), has good shooting & speed attributes (>80 rated), and a decent passing attribute' - because 'offensive players cost a lot more than defensive players.' (3) THE BEST-XI BUTTON IS UNRELIABLE: '**Never use the best IX button. It does not properly give you the best player for their position.** If you actually wanna see who's good for your each position, ask yourself what are you looking for in each position. For example, if I wanted a player to play right wing, I'd want someone with good speed, acceleration, control, and stamina. Along with that, they'd have to have a decent amount of shooting, passing, and strength.' So the auto-selection is a documented negative, and the per-position checklist replaces it. (4) THE FIRST-PURCHASE RULE: 'Your very first purchase should be a **RM, an LM and a CM** which should cost no more than a total of **500 coins**' out of the 1,500-coin starter grant - the rest goes to the stadium. (5) THE COACH-MIXING RULE: 'Use **fitness coaches first. They are safer**. Use **2 common techs for every 8 rare fitness coaches**. For GKs, use **1 rare and 4 commons** and repeat. Use legendary when GKR is higher than GKH.' (6) THE GK TARGET, more precise than the corpus's GKR>=GKH rule: 'Preferred: **90+ GKR with 0-10 difference to GKH**' - so the two stats should be close, not far apart. (7) THE TWO-STRIKER INVERSION: 'For 2-striker systems, **left foot on right and right foot on left** I find pretty good too' - which extends the corpus's footedness resolution to the striker pair specifically. (8) THE COACH-FARMING BAND CORROBORATED: 'buy/release players around **200-300** for common coaches. You might find some good legendary players in that process but the chance are small' - consistent with the corpus's 192-coin threshold. (9) A FOURTH CONTAMINATION: both searches returned FIFA Ultimate Team trading methods, FPL draft strategy and Mobile Legends drafting. **The general rule that falls out of it: any DLS topic with a famous analogue in another game gets contaminated, so always include 'Dream League Soccer' in the query, and discard on sight any source mentioning SBCs, Weekend League, FUT, chemistry styles, waivers or bans.**",
    "THE 50% RESALE RULE: a player sells for about HALF of what you paid - so buying is a sunk cost of half the price, and the only way to recover value is to keep and coach. The 200-300 coin coach-farming loop is therefore a deliberate loss-maker run for coaches, not coins. THE CAPTAIN CRITERIA REFINED: a fast forward with MINIMUM shooting who can at least shoot, never a goalkeeper or a defender, an 80-STAMINA floor rather than pace alone, tall (above 180cm) with shooting and speed above 80 - and Foden and Nunez are the long-term picks because they still fit a gold team. THE BEST-XI BUTTON IS UNRELIABLE - it does not give you the best player for the position, so use a per-position checklist instead. THE FIRST PURCHASE: an RM, an LM and a CM for no more than 500 coins. THE COACH-MIXING RULE: fitness first, 2 common techs per 8 rare fitness coaches, 1 rare plus 4 commons for GKs. THE GK TARGET: 90+ GKR with only a 0-10 difference to GKH. THE TWO-STRIKER INVERSION. A FOURTH CONTAMINATION and the general rule that follows from it.",
    "THE 50% RESALE RULE, THE CAPTAIN CRITERIA, AND A FOURTH CONTAMINATION",
    quality="community")

add_claim("THE 50% RESALE RULE, which the corpus did not carry and which prices every transfer decision: 'Since Dream League Soccer 2016h, **free transfers do not exist. Instead of releasing players, one must sell the player for half its purchase value.** They will go on to the market, priced at their value.' A second, independent source gives the same figure with a worked example: 'a player you may have bought for 1,400 gold will only sell for about **700 gold**.'", 2, "transfers/50-percent-resale-rule", [e_tm], notes="Two independent sources; reframes every transfer decision")
add_claim("What the 50% rule means for the plan: **buying a player is a sunk cost of half his price**, so the only way to recover value is to keep and coach him. And the 200-300 coin coach-farming loop is therefore a *deliberate* loss-maker you run for Common coaches, not for coins - which is exactly why the corpus's 192-coin threshold exists.", 3, "transfers/50-percent-rule-implications", [e_tm])
add_claim("THE CAPTAIN CRITERIA, REFINED beyond the corpus's 'pick the best attacker': '**You always want to get a fast forward with minimum shooting that can at least shoot.** These captains should help you get your first event win and your potential second legendary. **YOU SHOULD NEVER PICK OUT A GOALKEEPER OR A DEFENDER!**'", 3, "onboarding/captain-criteria-refined", [e_tm])
add_claim("THE 80-STAMINA CAPTAIN FLOOR: '**Get a player with high stamina as well, not just pace. I set a benchmark of min 80 stamina**, so in my book, many players on this list should be dropped. **Foden and Nunez are the best in this list for long term**, they (especially Foden) could still fit in your team when you get a full gold team.' So stamina, not pace, is the filter that separates a captain who lasts from one you replace.", 3, "onboarding/captain-80-stamina-floor", [e_tm], notes="Two named long-term captain picks")
add_claim("The fuller captain spec, from the original guide: a CF or WF who is '**reasonably tall (above 180cm), has good shooting & speed attributes (>80 rated), and a decent passing attribute**' - someone who can score in the air and on the ground AND take set pieces - because '**offensive players cost a lot more than defensive players.**'", 3, "onboarding/captain-full-spec", [e_tm])
add_claim("THE BEST-XI BUTTON IS UNRELIABLE - a documented negative: '**Never use the best IX button. It does not properly give you the best player for their position.**' Replace it with a per-position checklist: for a right winger, 'good speed, acceleration, control, and stamina. Along with that, they'd have to have a decent amount of shooting, passing, and strength.'", 3, "errata/best-xi-button-unreliable", [e_tm], notes="A negative the corpus did not carry; the auto-pick cannot be trusted")
add_claim("THE FIRST-PURCHASE RULE: 'Your very first purchase should be a **RM, an LM and a CM** which should cost no more than a total of **500 coins**' out of the 1,500-coin starter grant - the rest goes to the stadium. So the starter grant is a three-position purchase plus a stadium, not a player hunt.", 3, "onboarding/first-purchase-rule", [e_tm])
add_claim("THE COACH-MIXING RULE: 'Use **fitness coaches first. They are safer**. Use **2 common techs for every 8 rare fitness coaches**. For GKs, use **1 rare and 4 commons** and repeat. Use legendary when GKR is higher than GKH.' A sequencing rule for the corpus's coaching economy.", 3, "coaching/fitness-first-mixing-rule", [e_tm])
add_claim("THE GK TARGET, more precise than the corpus's GKR>=GKH rule: 'Preferred: **90+ GKR with 0-10 difference to GKH**' - so the two stats should be CLOSE, not far apart. A keeper with a huge GKR-GKH gap is not the target; a balanced one is.", 3, "goalkeeping/target-90-gkr-with-0-10-gap", [e_tm])
add_claim("THE TWO-STRIKER INVERSION: 'For 2-striker systems, **left foot on right and right foot on left** I find pretty good too' - which extends the corpus's footedness resolution (C-022) to the striker pair specifically, alongside the existing LB/LCB left-foot and RB/RCB right-foot rule.", 3, "matchcraft/two-striker-inversion", [e_tm])
add_claim("THE COACH-FARMING BAND CORROBORATED: 'buy/release players around **200-300** for common coaches. You might find some good legendary players in that process but the chance are small' - consistent with the corpus's 192-coin threshold, and a reminder that the loop's real output is coaches, with legendaries as an incidental bonus.", 3, "coaching/farming-band-200-300-corroborated", [e_tm])
add_claim("A FOURTH CONTAMINATION, and the general rule that falls out of it: searches on the transfer market and on Dream Draft returned **FIFA Ultimate Team trading methods (sniping filters, SBC demand cycles, Weekend League timing, the 5% EA tax, FUTBIN), Fantasy Premier League draft strategy (positional scarcity, waivers) and Mobile Legends drafting (bans, counter-picks, win conditions)**. **Any DLS topic with a famous analogue in another game gets contaminated.** So: always include 'Dream League Soccer' in the query, and discard on sight any source mentioning SBCs, Weekend League, FUT, chemistry styles, waivers or bans.", 2, "errata/fourth-contamination-general-rule", [e_tm], notes="Fourth contamination finding; states the general rule rather than a one-off")

for p in ['EV-501_resale_and_captain.html','EV-501b_onboarding_and_coaching.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
